<?php get_header(); ?><main id="pid-main" class="pid-content"><div class="pid-container"><?php if(have_posts()):while(have_posts()):the_post(); ?><article <?php post_class(); ?>><header><h1><?php the_title(); ?></h1></header><?php if(has_post_thumbnail())the_post_thumbnail('large'); ?><div class="entry-content"><?php the_content(); ?></div></article><?php endwhile;the_posts_pagination();else: ?><h1>Nothing found</h1><p>Please try another page or return to the homepage.</p><?php endif; ?></div></main><?php get_footer(); ?>